<?php
/**
 * Which word belongs to which date. The content lives in data/ as plain files:
 *   words.json     the answers, their facts and pins (the source of truth)
 *   schedule.json  an explicit date → word map, generated by bin/extend-schedule.mjs
 * A date missing from the schedule falls back to a computed word (day number mod the unpinned
 * pool) and is recorded, so WP admin and `wp spellar` can warn about it.
 *
 * bin/lib/puzzle.mjs is the JavaScript twin of this file; the tests compare the two.
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

const SPELLAR_KEY_PREFIX = 'spellar:';

function spellar_read_json( $name ) {
	static $cache = array();
	if ( ! array_key_exists( $name, $cache ) ) {
		$path           = SPELLAR_DIR . 'data/' . $name;
		$data           = is_readable( $path ) ? json_decode( (string) file_get_contents( $path ), true ) : null;
		$cache[ $name ] = is_array( $data ) ? $data : null;
	}
	return $cache[ $name ];
}

function spellar_words() {
	$words = spellar_read_json( 'words.json' );
	return is_array( $words ) ? $words : array();
}

function spellar_schedule() {
	$schedule = spellar_read_json( 'schedule.json' );
	if ( ! is_array( $schedule ) || empty( $schedule['launch'] ) || ! isset( $schedule['days'] ) || ! is_array( $schedule['days'] ) ) {
		return null;
	}
	return $schedule;
}

/* ---- Calendar dates as "YYYY-MM-DD", in UTC ---- */

function spellar_is_date( $value ) {
	if ( ! is_string( $value ) || ! preg_match( '/^(\d{4})-(\d{2})-(\d{2})$/', $value, $m ) ) {
		return false;
	}
	return checkdate( (int) $m[2], (int) $m[3], (int) $m[1] );
}

function spellar_date_ts( $date ) {
	list( $y, $m, $d ) = array_map( 'intval', explode( '-', $date ) );
	return gmmktime( 0, 0, 0, $m, $d, $y );
}

function spellar_days_between( $from, $to ) {
	return (int) round( ( spellar_date_ts( $to ) - spellar_date_ts( $from ) ) / DAY_IN_SECONDS );
}

function spellar_add_days( $date, $days ) {
	return gmdate( 'Y-m-d', spellar_date_ts( $date ) + $days * DAY_IN_SECONDS );
}

function spellar_utc_today() {
	return gmdate( 'Y-m-d' );
}

/** Puzzle #1 is the launch day. */
function spellar_puzzle_number( $date, $schedule ) {
	return spellar_days_between( $schedule['launch'], $date ) + 1;
}

/* ---- Words ---- */

function spellar_entry( $word ) {
	foreach ( spellar_words() as $entry ) {
		if ( isset( $entry['word'] ) && $entry['word'] === $word ) {
			return $entry;
		}
	}
	return null;
}

function spellar_fallback_word( $date, $schedule ) {
	$pool = array();
	foreach ( spellar_words() as $entry ) {
		if ( empty( $entry['pin'] ) && ! empty( $entry['word'] ) ) {
			$pool[] = $entry['word'];
		}
	}
	if ( ! $pool ) {
		return null;
	}
	sort( $pool, SORT_STRING );
	$n     = spellar_puzzle_number( $date, $schedule );
	$count = count( $pool );
	return $pool[ ( ( $n % $count ) + $count ) % $count ];
}

/**
 * The word for a date: [ 'word' => ..., 'fact' => ..., 'pinned' => bool, 'fallback' => bool ], or null.
 */
function spellar_word_for( $date ) {
	$schedule = spellar_schedule();
	if ( ! $schedule ) {
		return null;
	}
	$fallback = ! isset( $schedule['days'][ $date ] );
	$word     = $fallback ? spellar_fallback_word( $date, $schedule ) : $schedule['days'][ $date ];
	$entry    = $word ? spellar_entry( $word ) : null;
	if ( ! $entry || empty( $entry['fact'] ) ) {
		return null;
	}
	if ( $fallback ) {
		spellar_note_fallback( $date );
	}
	return array(
		'word'     => $entry['word'],
		'fact'     => $entry['fact'],
		'pinned'   => ! empty( $entry['pin'] ),
		'fallback' => $fallback,
	);
}

/** Remembers dates served by the fallback (one write per date), for the admin notice and the CLI. */
function spellar_note_fallback( $date ) {
	$seen = get_option( 'spellar_fallback_dates', array() );
	if ( ! is_array( $seen ) ) {
		$seen = array();
	}
	if ( in_array( $date, $seen, true ) ) {
		return;
	}
	$seen[] = $date;
	$seen   = array_slice( $seen, -30 );
	update_option( 'spellar_fallback_dates', $seen, false );
}

/** Spoiler shield, not security: UTF-8 bytes XORed with "spellar:" + the date, then base64. */
function spellar_encode( $text, $date ) {
	$key = SPELLAR_KEY_PREFIX . $date;
	$len = strlen( $key );
	$out = '';
	for ( $i = 0, $n = strlen( $text ); $i < $n; $i++ ) {
		$out .= chr( ord( $text[ $i ] ) ^ ord( $key[ $i % $len ] ) );
	}
	return base64_encode( $out ); // phpcs:ignore WordPress.PHP.DiscouragedPHPFunctions.obfuscation_base64_encode
}

/** Days of schedule left after today (negative when it has already run out). */
function spellar_schedule_days_left() {
	$schedule = spellar_schedule();
	if ( ! $schedule || ! $schedule['days'] ) {
		return -1;
	}
	$dates = array_keys( $schedule['days'] );
	sort( $dates, SORT_STRING );
	return spellar_days_between( spellar_utc_today(), end( $dates ) );
}

/** Problems worth an admin's attention: an empty list when all is well. */
function spellar_schedule_warnings() {
	$warnings = array();
	if ( ! spellar_schedule() ) {
		$warnings[] = 'data/schedule.json is missing or unreadable, so no puzzle can be served.';
		return $warnings;
	}
	$left = spellar_schedule_days_left();
	if ( $left < 60 ) {
		$warnings[] = sprintf( 'The schedule runs out in %d days. Run bin/extend-schedule.mjs and deploy.', $left );
	}
	$fallbacks = get_option( 'spellar_fallback_dates', array() );
	$recent    = array_filter(
		is_array( $fallbacks ) ? $fallbacks : array(),
		function ( $d ) {
			return spellar_days_between( $d, spellar_utc_today() ) <= 7;
		}
	);
	if ( $recent ) {
		$warnings[] = 'These dates had no word in the schedule and used a computed word instead: ' . implode( ', ', $recent ) . '.';
	}
	return $warnings;
}
